INSERT INTO m_permission (grouping, code, entity_name, action_name, can_maker_checker)
SELECT 'self_service', 'READ_SELFACCESSAUDIT', 'SELFACCESSAUDIT', 'READ', FALSE
WHERE NOT EXISTS (
    SELECT 1 FROM m_permission WHERE code = 'READ_SELFACCESSAUDIT'
);

INSERT INTO m_permission (grouping, code, entity_name, action_name, can_maker_checker)
